// Runtime config, injected by /config.js (generated by scripts/write-config.js).
// If that file is missing, the app runs in local-only mode.
const raw = globalThis.__APP_CONFIG__ || {};

export const config = Object.freeze({
  supabaseUrl: raw.supabaseUrl || '',
  supabaseAnonKey: raw.supabaseAnonKey || '',
  get cloudEnabled() {
    return Boolean(this.supabaseUrl && this.supabaseAnonKey);
  },
});
